function [bsm,interpolSamples] = removePacingSpike(BSM)difSig=abs(diff(abs(diff(rms(BSM)))));nSamples= 22;% nSamples= 32;spikeFound=0;spikes = [];spikeSamples = [];interpolSamples = [];dd=difSig;ddi=find(dd>3*std(dd));dd(max(1,min(ddi)-20):min(length(dd),max(ddi)+30))=[];stdDifSig = 10*std(dd);if max(difSig) > 10*max(dd)     for i = 2 : length(difSig)        if spikeFound            if difSig(i) < stdDifSig && difSig(i-1) < stdDifSig                spikeFound = 0;            else                spikes{end}.samples = [spikes{end}.samples i];                end        elseif difSig(i) > stdDifSig            spikes{length(spikes)+1}.samples = i;            spikeFound =1;        end        end    for i= length(spikes):-1:1        spikeSamples=[spikes{i}.samples spikeSamples];    end    minSample = min(spikeSamples(spikeSamples>110));    if max(spikeSamples) > minSample        spikeSamples( spikeSamples > minSample+70 & spikeSamples < minSample+300) =[];    end        sig=BSM;        index = [1 find(diff(spikeSamples)>1)+1 ];    interpolSamples=[];    for i=1:length(index)        interpolSamples=[interpolSamples spikeSamples(index(i)):min(spikeSamples(index(i))+ nSamples,size(BSM,2))];    end    t= 1:size(BSM,2);    t(interpolSamples)=[];    interpolSamples = unique(interpolSamples);    sig(:,interpolSamples)=[];    bsm=BSM;    if diff(range(interpolSamples)) < 40        index = 1;        interpolSamples = interpolSamples(1):interpolSamples+ nSamples;        for i=1:size(BSM,1)            bsm(i,interpolSamples) = interp1(t,sig(i,:) ,interpolSamples,'spline');                end    else        for i=1:size(BSM,1)            bsm(i,interpolSamples) = interp1(t,sig(i,:) ,interpolSamples,'spline');                end    end%     bsm = lowpassma(bsm,3);    disp(['removed ' num2str(length(index)) ' pacing spikes']);else    bsm=BSM;end